    public InventSiteId             frmInitialInventSiteId;
    public UserId                   frmUserId;
    public HcmWorkerRecId           frmHcmWorkerRecId;
    public HCMWorker                frmHCMWorker;
    public AVAWorkerInventSite      frmAVAWorkerInventSite;

    public Args                     frmArgs;
    public InventTransferId         frmInventTransferId;
    public InventTransferTable      frmInventTransferTable;
    public InventTransferLine       frmInventTransferLine;

    public boolean                              frmReleaseForShipmentMode;
    public AVAInventTransferLineBackOrderTmp    frmAVAInventTransferLineBackOrderTmp;
    public boolean                              frmShipmentDateConfirmedOverwrite;
    public SalesShippingDateConfirmed           frmShipmentDateConfirmed;
    public boolean                              frmReleaseForShipmentSaveWhenClosing;

    public AVABackOrderReleaseHandling          frmAVABackOrderReleaseHandling;

    public KCS_TonnageSetup         frmKCS_TonnageSetup;

    public int                      frmBackgroundColor;
    public int                      frmColorScheme;

    public boolean                  frmCloseESC;
    public boolean                  frmCloseESCCancel;
    public boolean                  frmCloseESCOk;

    public AVAItemSetParameters     frmAVAItemSetParameters;


