/// <summary>
///    AVA <c>registerDatasourceOnQueryingEvent</c> method.
/// </summary>
public void registerDatasourceOnQueryingEvent()
{
    InventTransferLine_DS.OnQueryExecuting += eventhandler(this.parmFilterFormQueryEventHandler().applyFilter);
}

/// <summary>
///    AVA <c>docCursor</c> method.
/// </summary>
/// <returns>
///    <c>Common</c> as return value
/// </returns>
public Common docCursor()
{
    Common docCursor;

    docCursor = super();

    if (docCursor.TableId == tableNum(InventDim))
    {
        docCursor = inventTransferLine;
    }

    return docCursor;
}

/// <summary>
///    AVA <c>initFrmValues</c> method.
/// </summary>
void initFrmValues()
{
    Common          locCommon;

    frmUserId               = curUserId();
    frmHcmWorkerRecId       = HcmWorkerLookup::currentWorker();
    frmHCMWorker            = HCMWorker::find(frmHcmWorkerRecId);
    frmAVAWorkerInventSite  = AVAWorkerInventSite::find(frmHCMWorker.PersonnelNumber);

    frmInitialInventSiteId  = frmAVAWorkerInventSite.InventSiteId;

    frmAVABackOrderReleaseHandling = new AVABackOrderReleaseHandling();
    frmAVABackOrderReleaseHandling.init();

    frmAVAItemSetParameters = AVAItemSetParameters::find();


    if (element.args().caller() is SysIFilterProvider)
    {
        element.args().lookupRecord(null);
        element.args().record(null);
    }

    if(element.args())
    {
        frmArgs = new Args();
        frmArgs = element.args();
    }

    if(     element.args()
        &&  element.args().menuItemName() == menuitemDisplayStr(AVAInventTransferLineBackOrderReleaseShipment)  )
    {
        if(frmArgs.record())
        {
            locCommon = frmArgs.record();

            switch(locCommon.TableId)
            {
                case Tablenum(InventTransferTable):
                    frmInventTransferTable  = locCommon;
                    frmInventTransferId     = frmInventTransferTable.TransferId;
                    break;

                case Tablenum(InventTransferLine):
                    frmInventTransferLine   = locCommon;
                    frmInventTransferId     = frmInventTransferLine.TransferId;
                    frmInventTransferTable  = InventTransferTable::find(frmInventTransferId);
                    break;
            }
            frmReleaseForShipmentMode = true;
        }
    }

    frmKCS_TonnageSetup = KCS_TonnageSetup::find();
}

/// <summary>
///    AVA <c>init</c> method.
/// </summary>
void init()
{
    date            initialDateValue;
    FormRealControl locFormRealControl;
    this.initFrmValues();

    super();

    InventTransferLine_DS.query().dataSourceTable(tablenum(InventTransferLine)).clearRange(fieldnum(InventTransferLine, ShipDate)); //ToDo: check originally InventTransferLine.ConfirmedDlv

    backorderDateInventTransferLine = InventTransferLine_DS.query().dataSourceTable(tablenum(InventTransferLine)).addRange(fieldnum(InventTransferLine, ShipDate)); //ToDo: check originally InventTransferLine.ConfirmedDlv

    initialDateValue = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone()) - 1;

    if (    element.args() 
        &&  element.args().menuItemName() != menuitemDisplayStr(AVASalesDelayedOrders)   )      //ToDo: check, not needed
    {
        int backOrderDays = real2int(MCROrderParameters::find().BackorderDays);
        if (backOrderDays > 1)
        {
            initialDateValue -= (backorderDays -1);
        }
    }

    if(frmReleaseForShipmentMode)
    {
        element.design().caption("@NDX:NXAReleaseForShipment");

        TransferToInventTransferLine.enabled(true);

        GridFilterGroupStandard.enabled(false);

        ReleaseForShipmentGroup.visible(true);
        AVAInventTransferLineBackOrderReleaseShipment.visible(false);

        InventTransferLine_KCS_SOCPickingReleaseIndicator.visible(false);
        InventTransferLineTmpFields.visible(true);
        /**///InventTransfer_KCS_SOCPickingReleaseIndicator.visible(true);

        initialDateValue = maxDate();
    }
    else
    {
        GridFilterInventSiteId.enabled(true);

        ReleaseForShipmentGroup.visible(false);
        MenuButtonApprovals.visible(false);
    }

    backorderDate.dateValue(initialDateValue);

    element.updateDesign(InventDimFormDesignUpdate::Init);

    if (#PdsCatchWeightEnabled)
    {
        //InventTransferLine_PdsCWQty.visible(true);
        InventTransferPdsCWQtyRow.visible(true);
    }

    GridFilterInventSiteId.text(frmInitialInventSiteId);

    this.initQuery();
    this.replaceSortOrder();
    this.addFilterPaneRanges();
    this.initQueryRanges();

    if(frmReleaseForShipmentMode)
    {
        if(frmInventTransferLine.RecId && frmInventTransferLine.RemainStatus == InventTransferRemainStatus::Receiving)   //ToDo:Check Button group Approval
        {
            ButtonGroupApproval.enabled(false);
        }
        else if(frmInventTransferTable.RecId && frmInventTransferTable.TransferStatus == InventTransferStatus::Received)    //ToDo:Check Button group Approval
        {
            ButtonGroupApproval.enabled(false);
        }
    }

    //locFormRealControl  = element.design().controlName(formControlStr(AVAInventTransferLineBackOrder, ReleasForShipment_ShipmentWorkload));
    locFormRealControl  = ReleasForShipment_ShipmentWorkload;
    frmColorScheme      = locFormRealControl.colorScheme();
    frmBackgroundColor  = locFormRealControl.backgroundColor();
}

/// <summary>
///    AVA <c>inventDimSetupObject</c> method.
/// </summary>
/// <returns>
///    <c>InventDimCtrl_Frm_OnhandItem</c> as return value
/// </returns>
InventDimCtrl_Frm_OnhandItem inventDimSetupObject()
{
    InventDimParm   inventDimParm;

    if (!inventDimFormSetup)
    {
        inventDimFormSetup                  = InventDimCtrl_Frm_OnhandItem::newFromForm(element);
        inventDimFormSetup.parmLargeRightClickForm(NoYes::Yes);
        inventDimFormSetup.parmGroupByNameAlias(NoYes::Yes);
        inventDimParm                       =  inventDimFormSetup.parmDimParmVisible();
        inventDimParm                       = inventDimFormSetup.parmDimParmVisible();

        inventDimParm.InventSiteIdFlag      = NoYes::Yes;
        inventDimParm.InventLocationIdFlag  = NoYes::Yes;
        inventDimFormSetup.parmDimParmVisible(inventDimParm);
    }
    return inventDimFormSetup;
}

/// <summary>
///    AVA <c>updateDesign</c> method.
/// </summary>
/// <param name="mode">
///    <c>InventDimFormDesignUpdate</c> as type
/// </param>
void updateDesign(InventDimFormDesignUpdate mode)
{
    switch (mode)
    {
        case InventDimFormDesignUpdate::Init          :
            // No break
        case InventDimFormDesignUpdate::LinkActive    :
            element.inventDimSetupObject().initFromCaller();
            element.inventDimSetupObject().parmCtrlItemId(GroupInventSum_Item_ItemId);

            if (mode == InventDimFormDesignUpdate::Init)
            {
                if (element.inventDimSetupObject().parmDimParmVisibleGrid().ItemIdFlag == NoYes::No)
                {
                    GroupInventSum_ItemName.visible(false);
                }
            }
            element.inventDimSetupObject().parmDimParmVisible(element.inventDimSetupObject().parmDimParmVisibleGrid());
            // No break
        case InventDimFormDesignUpdate::Active        :
            element.inventDimSetupObject().formActiveSetup();
            element.inventDimSetupObject().formSetControls(true,true);
            break;

        default :
            throw error(strFmt("@SYS54195",funcName()));
    }
}

