/// <summary>
///     AVA <c>replaceSortOrder</c> method.
/// </summary>
public void replaceSortOrder()
{
    QueryBuildDataSource inventTransferLineQBDS;

    inventTransferLineQBDS = InventTransferLine_DS.query().dataSourceName(InventTransferLine_DS.name());
    inventTransferLineQBDS.clearSortIndex();
    inventTransferLineQBDS.addSortField(fieldNum(InventTransferLine, TransferId), SortOrder::Ascending);
    inventTransferLineQBDS.addSortField(fieldNum(InventTransferLine, LineNum), SortOrder::Ascending);
}

/// <summary>
///     AVA <c>initQueryRanges</c> method.
/// </summary>
public void initQueryRanges()
{
    QueryBuildDataSource inventTransferLineQBDS;
    QueryBuildDataSource inventSumQBDS;

    inventTransferLineQBDS = InventTransferLine_DS.query().dataSourceName(InventTransferLine_DS.name());
    SysQuery::findOrCreateRange(inventTransferLineQBDS, fieldNum(InventTransferLine, RemainStatus)).value(queryValue(InventTransferRemainStatus::Shipping));
    SysQuery::findOrCreateRange(inventTransferLineQBDS, fieldNum(InventTransferLine, QtyRemainShip)).value(SysQuery::valueNot(0));

    if(frmInventTransferLine.RecId)
    {
        SysQuery::findOrCreateRange(inventTransferLineQBDS, fieldNum(InventTransferLine, InventTransId)).value(frmInventTransferLine.InventTransId);
    }
    else if(frmInventTransferTable.RecId)
    {
        SysQuery::findOrCreateRange(inventTransferLineQBDS, fieldNum(InventTransferLine, TransferId)).value(frmInventTransferTable.TransferId);
    }

    inventSumQBDS = InventSum_DS.query().dataSourceName(inventSum_DS.name());
    SysQuery::findOrCreateRange(inventSumQBDS, fieldNum(InventSum, InventSiteId)).value(queryValue(frmAVAWorkerInventSite));
    QueryBuildRange         inventTransferStatusQbr = SysQuery::findOrCreateRange(InventTransferTable_ds.query().dataSourceTable(tableNum(InventTransferTable)), fieldNum(InventTransferTable, TransferStatus));
    if (inventTransferStatusQbr)
    {
        if (frmInventTransferId == '')
        {
            inventTransferStatusQbr.value(SysQuery::valueNot(InventTransferStatus::Shipped));
        }
        else
        {
            inventTransferStatusQbr.value(SysQuery::valueUnlimited());
        }
    }

    this.setQueryRangeGridFilterInventSiteId();

    SysQuery::findOrCreateRange(inventTransferLineQBDS, fieldNum(InventTransferLine, AVAItemSet)).value(SysQuery::valueNot(NoYes::Yes));
}

/// <summary>
