///    AVA <c>deleteAVAInventTransferLineTmpTable</c> method.
/// </summary>
private void deleteAVAInventTransferLineTmpTable()
{
    frmAVAInventTransferLineBackOrderTmp = AVAInventTransferLineBackOrderTmp_DS.getFirst() as AVAInventTransferLineBackOrderTmp;

    delete_from frmAVAInventTransferLineBackOrderTmp;
}

/// <summary>
///    AVA <c>createInventTransferLineTmpTableRecord</c> method.
/// </summary>
/// <param name="mode">
///    <c>InventTransferLine</c> as type
/// </param>
/// <returns>
///    <c>AVAInventTransferLineBackOrderTmp</c> as return value
/// </returns>
private AVAInventTransferLineBackOrderTmp createInventTransferLineTmpTableRecord(InventTransferLine _inventTransferLine, AVAInventTransferLineBackOrderTmp _avaInventTransferLineBackOrderTmp)
{
    InventTransferLine                  locInventTransferLine;
    AVAInventTransferLineBackOrderTmp   locAVAInventTransferLineBackOrderTmp;

    locInventTransferLine                   = _InventTransferLine;
    locAVAInventTransferLineBackOrderTmp    = _avaInventTransferLineBackOrderTmp;

    locAVAInventTransferLineBackOrderTmp.clear();
    locAVAInventTransferLineBackOrderTmp.InventTransferLineRefRecId     = locInventTransferLine.RecId;
    locAVAInventTransferLineBackOrderTmp.TransferId                     = locInventTransferLine.TransferId;
    locAVAInventTransferLineBackOrderTmp.InventTransId                  = locInventTransferLine.InventTransId;
    locAVAInventTransferLineBackOrderTmp.ItemId                         = locInventTransferLine.ItemId;
    locAVAInventTransferLineBackOrderTmp.InventDimId                    = locInventTransferLine.InventDimId;
    locAVAInventTransferLineBackOrderTmp.PdsCWQtyTransfer               = locInventTransferLine.PdsCWQtyTransfer;
    locAVAInventTransferLineBackOrderTmp.QtyTransfer                    = locInventTransferLine.QtyTransfer;
    locAVAInventTransferLineBackOrderTmp.ReceiveDate                    = locInventTransferLine.ReceiveDate;
    locAVAInventTransferLineBackOrderTmp.ShipDate                       = locInventTransferLine.ShipDate;

    locAVAInventTransferLineBackOrderTmp.AVAStockAvailability           = locInventTransferLine.avaGetStockAvailablity();
    locAVAInventTransferLineBackOrderTmp.KCS_SOCPickingReleaseIndicator = locInventTransferLine.KCS_SOCPickingReleaseIndicator;
    locAVAInventTransferLineBackOrderTmp.Processed                      = NoYes::No;

    locAVAInventTransferLineBackOrderTmp.insert();

    return locAVAInventTransferLineBackOrderTmp;
}

/// <summary>
///    AVA <c>createInventTransferLineTmpTableData</c> method.
/// </summary>
/// <returns>
///    <c>AVAInventTransferLineBackOrderTmp</c> as return value
/// </returns>
private AVAInventTransferLineBackOrderTmp createInventTransferLineTmpTableData()
{
    InventTransferLine                  locInventTransferLine;
    AVAInventTransferLineBackOrderTmp   locAVAInventTransferLineBackOrderTmp;
    TransDate                           locTransDate;

    this.deleteAVAInventTransferLineTmpTable();

    if(frmInventTransferTable.RecId)
    {
        while select locInventTransferLine
        where locInventTransferLine.TransferId == frmInventTransferTable.TransferId
        {
            locAVAInventTransferLineBackOrderTmp = this.createInventTransferLineTmpTableRecord(locInventTransferLine, locAVAInventTransferLineBackOrderTmp);

            locTransDate = locInventTransferLine.avaDateNextAvailable();
            if(ReleasForShipment_DateNextAvailableMax.dateValue() < locTransDate)
            {
                ReleasForShipment_DateNextAvailableMax.dateValue(locTransDate);
            }
        }
    }
    else
    {
        locInventTransferLine  = InventTransferLine_DS.getFirst(true) as InventTransferLine;
        if (locInventTransferLine)
        {
            while (locInventTransferLine)
            {
                locAVAInventTransferLineBackOrderTmp = this.createInventTransferLineTmpTableRecord(locInventTransferLine, locAVAInventTransferLineBackOrderTmp);

                locTransDate = locInventTransferLine.avaDateNextAvailable();
                if(ReleasForShipment_DateNextAvailableMax.dateValue() < locTransDate)
                {
                    ReleasForShipment_DateNextAvailableMax.dateValue(locTransDate);

                }
                locInventTransferLine = InventTransferLine_DS.getNext() as InventTransferLine;
            }
        }
    }
    return locAVAInventTransferLineBackOrderTmp;
}

/// <summary>
///    AVA <c>close</c> method.
/// </summary>
public void close()
{
    if(frmCloseESC && !frmCloseESCCancel)
    {
        frmCloseESCOk = true;
    }
    if(!frmCloseESCCancel)
    {
        frmReleaseForShipmentSaveWhenClosing = true;

        element.handleTmpTableChanges();

        frmReleaseForShipmentSaveWhenClosing = false;
    }

    super();
}

/// <summary>
///    AVA <c>closeOk</c> method.
/// </summary>
public void closeOk()
{
    frmReleaseForShipmentSaveWhenClosing = true;

    element.handleTmpTableChanges();

    frmReleaseForShipmentSaveWhenClosing = false;

    super();
}

/// <summary>
///    AVA <c>closeCancel</c> method.
/// </summary>
public void closeCancel()
{
    if(frmCloseESC)
    {
        frmCloseESCCancel = true;
    }

    super();
}

