/// <summary>
///    AVA <c>releaseActualPosition</c> method.
/// </summary>
/// <param name="_avaInventTransferLineBackOrderTmp">
///    <c>AVAInventTransferLineBackOrderTmp</c> as type
/// </param>
private void releaseInventTransferLinePosition(AVAInventTransferLineBackOrderTmp _avaInventTransferLineBackOrderTmp = null)
{
    InventTransferLine                  locInventTransferLine;
    AVAInventTransferLineBackOrderTmp   locAVAInventTransferLineBackOrderTmp;

    AVAStockAvailability                locAVAStockAvailability;

    boolean                             locCheckFailed;

    if(_avaInventTransferLineBackOrderTmp)
    {
        locAVAInventTransferLineBackOrderTmp = _avaInventTransferLineBackOrderTmp;
    }
    else
    {
        locAVAInventTransferLineBackOrderTmp = AVAInventTransferLineBackOrderTmp;
    }
    locInventTransferLine = InventTransferLine::findRecId(locAVAInventTransferLineBackOrderTmp.InventTransferLineRefRecId);

    locAVAStockAvailability = locInventTransferLine.avaGetStockAvailablity();

    if(locAVAStockAvailability == AVAStockAvailability::NotAvailable)
    {
        locCheckFailed = checkFailed("@NDX:NXAReleasePositionNotPossible");
    }
    else if(    locAVAStockAvailability == AVAStockAvailability::PartitialAvailable 
            &&  !locAVAInventTransferLineBackOrderTmp.KCS_SOCPickingReleaseIndicator         )
    {
        locCheckFailed = checkFailed("@NDX:NXASwitchReleaseForShipmentHaveToBeSet");
    }
    else if(    locAVAStockAvailability == AVAStockAvailability::Available 
            ||  locAVAStockAvailability == AVAStockAvailability::IndividualRequired)
    {
        ttsBegin;
        if(!locAVAInventTransferLineBackOrderTmp.KCS_SOCPickingReleaseIndicator)
        {
            locAVAInventTransferLineBackOrderTmp.selectForUpdate(true);
            locAVAInventTransferLineBackOrderTmp.KCS_SOCPickingReleaseIndicator  = NoYes::Yes;
            locAVAInventTransferLineBackOrderTmp.update();

            locInventTransferLine.avaItemSetInventTransferLineSetKCS_SOCPickingReleaseIndicator(true); // with siblings

            //element.processTmpTablePositions(locAVAInventTransferLineBackOrderTmp); // deactivated for Indicator change only
        }
        element.processTmpTablePositions(locAVAInventTransferLineBackOrderTmp); // added for date change even position release indiccator was not changed
        //element.releaseSingleInventTransferLinePosition(locInventTransferLine); // managed over tmpTable process, not needed anymore
        ttsCommit;
    }
}

/// <summary>
///    AVA <c>releaseSingleInventTransferLinePosition</c> method.
/// </summary>
/// <param name="_inventTransferLine">
///    <c>InventTransferLine</c> as type
/// </param>
private void releaseSingleInventTransferLinePosition(InventTransferLine _inventTransferLine)
{
    InventTransferLine   locInventTransferLine;

    ttsBegin;
    locInventTransferLine = _inventTransferLine;
    locInventTransferLine.selectForUpdate(true);
    locInventTransferLine.KCS_SOCPickingReleaseIndicator = NoYes::Yes;
    locInventTransferLine.update();

    locInventTransferLine.avaItemSetInventTransferLineSetKCS_SOCPickingReleaseIndicator(true); // with siblings

    locInventTransferLine.avaUpdateInventTransferTableKCS_PickingReleaseIndicator();
    ttsCommit;

    InventTransferLine_DS.reread();
    InventTransferLine_DS.refresh();
}

/// <summary>
///    AVA <c>processTmpTablePositions</c> method.
/// </summary>
/// <param name="_singleAVAInventTransferLineBackOrderTmp">
///    <c>AVAInventTransferLineBackOrderTmp</c> as type
/// </param>
private void processTmpTablePositions(AVAInventTransferLineBackOrderTmp  _singleAVAInventTransferLineBackOrderTmp = null)
{
    InventTransferLine          locInventTransferLine;
    AVAStockAvailability        locAVAStockAvailability;
    RefRecId                    locSingleAVAInventTransferLineBackOrderTmpRecId;
    boolean                     tmpTableModified;
    boolean                     inventTransferLineModified;

    boolean                     locApprovalMarkAvailableFound;

    boolean                     locReleaseFunctionsReservations;

    SalesShippingDateConfirmed  locShippingDate;
    boolean                     locShippingDateOverwrite;

    boolean                     locReleaseFunctionReleaseMarked;
    boolean                     locReleaseFunctionsShippingDateTmp;
    boolean                     locReleaseFunctionsReservationsTmp;

    boolean                     locReleaseFunctionReleaseMarkedSaveOpenChanges;

    InventQty                   locRemainInventQtyToReserve;

    DialogButton                locDialogButton;

    boolean                     locGetInventTransferLinesFromDB;


    void processReservation()
    {
        if( locInventTransferLine.QtyRemainShip > 0.0)
        {
            locRemainInventQtyToReserve = locInventTransferLine.avaRemainInventQtyNotReserved();
            if(locRemainInventQtyToReserve)
            {
                if(inventTransferLineModified)
                {
                    locInventTransferLine.selectForUpdate(true);
                    locInventTransferLine.update();

                    locInventTransferLine.avaUpdateInventTransferTableKCS_PickingReleaseIndicator();
                    inventTransferLineModified = false;
                }
                locInventTransferLine.avaReserveInventTransferLine(locInventTransferLine, locRemainInventQtyToReserve);
                locInventTransferLine.reread();
                inventTransferLineModified = false;
            }
        }
    }

    locSingleAVAInventTransferLineBackOrderTmpRecId = _singleAVAInventTransferLineBackOrderTmp.RecId;

    frmAVABackOrderReleaseHandling.parmReleaseFunctionReleaseAllPossible(true);                     // regard all position(s) as releasable until one is found as not releasable

    if(frmAVABackOrderReleaseHandling.parmReleaseFunctionReleaseMarked())                           // "Teilfreigabe"
    {
        if(     frmAVABackOrderReleaseHandling.parmReleasePosition()
            &&  _singleAVAInventTransferLineBackOrderTmp.Processed   )
        {
            frmAVABackOrderReleaseHandling.parmReleaseFunctionsReservations(false);                 // "Freigabefunktionen - Reservierungen" allready done in single step
        }
    }


    // pre check tmp table for changes
    frmAVABackOrderReleaseHandling.parmApprovalMarkAvailablePossible(false);

    while select AVAInventTransferLineBackOrderTmp
    {
        locInventTransferLine           = InventTransferLine::findTransIdShip(AVAInventTransferLineBackOrderTmp.InventTransId);
        frmAVABackOrderReleaseHandling.currentSetValuesTables(locInventTransferLine, AVAInventTransferLineBackOrderTmp);

        locApprovalMarkAvailableFound   = false;

        if(frmAVABackOrderReleaseHandling.parmApprovalMarkAvailable())                              // "Verfügbare markieren" - Grün markieren
        {
            if(frmAVABackOrderReleaseHandling.currentIsAvailableOrIndividual())
            {
                if(frmAVABackOrderReleaseHandling.currentReleaseIndicatorBothNo())
                {
                    locApprovalMarkAvailableFound = true;                                           // current position possible to be marked
                }
                if(     locApprovalMarkAvailableFound
                    &&  locInventTransferLine.AVAItemSetComponent)                                  // item set component, check other components
                {
                    locApprovalMarkAvailableFound = this.checkItemSetComponentReleasable(locInventTransferLine);
                }
            }
            if(     !frmAVABackOrderReleaseHandling.parmApprovalMarkAvailablePossible() 
                &&  locApprovalMarkAvailableFound)                                                  // untill now no markable position found but current is markable
            {
                frmAVABackOrderReleaseHandling.parmApprovalMarkAvailablePossible(true);             // at least one position possible to be marked
            }
        }                                          

        if(frmAVABackOrderReleaseHandling.parmReleaseFunctionReleaseMarked())                       // "Teilfreigabe"
        {
            if(     frmAVABackOrderReleaseHandling.parmReleasePosition()            == false        // "keine Positionsfreigabe"
                ||  (       frmAVABackOrderReleaseHandling.parmReleasePosition()    == true         // "Positionsfreigabe"
                        &&  locSingleAVAInventTransferLineBackOrderTmpRecId
                        &&  locSingleAVAInventTransferLineBackOrderTmpRecId         == AVAInventTransferLineBackOrderTmp.RecId) )
            {
                if(!frmAVABackOrderReleaseHandling.parmReleaseFunctionReleaseMarkedPossible())
                {
                    if(locApprovalMarkAvailableFound)                                               // current position possible to be marked, but not marked
                    {
                        frmAVABackOrderReleaseHandling.parmReleaseFunctionReleaseMarkedPossible(true);
                    }
                    if(frmAVABackOrderReleaseHandling.currentReleaseIndicatorNo2Yes())              // current position marked for release
                    {
                        frmAVABackOrderReleaseHandling.parmReleaseFunctionReleaseMarkedPossible(true);
                    }
                }
            }
        }

        if(frmAVABackOrderReleaseHandling.parmReleaseFunctionReleaseAll())                          // "Komplettfreigabe"
        {
            if(frmAVABackOrderReleaseHandling.currentIsNotAvailableOrIndividual())
            {
                frmAVABackOrderReleaseHandling.parmReleaseFunctionReleaseAllPossible(false);        // current position not releasable, not all positions are releasable
            }
        }

        if(frmAVABackOrderReleaseHandling.parmReleaseFunctionsReservations())                       // "Freigabefunktionen - Reservierungen"
        {
            if(     frmAVABackOrderReleaseHandling.parmReleasePosition()            == false        // "keine Positionsfreigabe"
                ||  (       frmAVABackOrderReleaseHandling.parmReleasePosition()    == true         // "Positionsfreigabe"
                        &&  locSingleAVAInventTransferLineBackOrderTmpRecId
                        &&  locSingleAVAInventTransferLineBackOrderTmpRecId         == AVAInventTransferLineBackOrderTmp.RecId)    )
            {
                if(frmAVABackOrderReleaseHandling.currentIsAvailableOrIndividual())
                {
                    if(     (   frmAVABackOrderReleaseHandling.currentReleaseIndicatorBothNo() ||  frmAVABackOrderReleaseHandling.currentReleaseIndicatorNo2Yes()   )
                        &&  locInventTransferLine.qtyRemainShip > 0.0)                              // ToDo: check remainInventPhysical
                    {
                        frmAVABackOrderReleaseHandling.parmReleaseFunctionsReservationsPossible(true);

                        if(!locRemainInventQtyToReserve)                                            // first hit for not reserved qtys
                        {
                            locRemainInventQtyToReserve = locInventTransferLine.avaRemainInventQtyNotReserved();
                        }
                    }
                }
            }
        }

        if(frmAVABackOrderReleaseHandling.parmApprovalSaveOpenChanges())                            // "Änderungen speichern"
        {
            if(frmAVABackOrderReleaseHandling.currentReleaseIndicatorDifferent())
            {
                frmAVABackOrderReleaseHandling.parmApprovalSaveOpenChangesPossible(true);           // KCS_SOCPickingReleaseIndicator has changed in at least one position

                if(frmAVABackOrderReleaseHandling.currentReleaseIndicatorNo2Yes())
                {
                    locReleaseFunctionReleaseMarkedSaveOpenChanges = true;                          // KCS_SOCPickingReleaseIndicator activated in at least one position

                    if(!locRemainInventQtyToReserve)
                    {
                        locRemainInventQtyToReserve = locInventTransferLine.avaRemainInventQtyNotReserved();
                    }
                }
            }
        }
    }

    // react on results of check                                                                    
    if(     frmAVABackOrderReleaseHandling.parmReleaseFunctionReleaseAll()                          // "Komplettfreigabe"
        &&  !frmAVABackOrderReleaseHandling.parmReleaseFunctionReleaseAllPossible())                // not all tmp table positions available or individual
    {
        info("@NDX:NXANotAllPositionsDeliverableMarkSingleOnes");
    }

    if(     frmReleaseForShipmentSaveWhenClosing                                                    // save when closing
        &&  frmAVABackOrderReleaseHandling.parmApprovalSaveOpenChangesPossible()                    // KCS_SOCPickingReleaseIndicator has changed in at least one position
        &&  !frmCloseESCOk                                                      )                   // closed by ESC but with save changes
    {
        locDialogButton = Box::yesNo(   "@SYS21594",
                                        DialogButton::Yes,
                                        "@NDX:NXAReleaseForShipment"
                                        );
        if (locDialogButton != DialogButton::Yes)
        {
            frmAVABackOrderReleaseHandling.parmApprovalSaveOpenChanges(false);                      // "Änderungen speichern" but leave without changes
        }
    }

    if(     frmAVABackOrderReleaseHandling.parmReleaseFunctionsReservations()
        &&  !frmAVABackOrderReleaseHandling.parmReleaseFunctionsReservationsPossible()  )           // "Freigabefunktionen - Reservierungen" but no positions to be reserved
    {
        frmAVABackOrderReleaseHandling.parmReleaseFunctionsReservations(false);
    }

    if(     frmAVABackOrderReleaseHandling.parmApprovalSaveOpenChanges()
        &&  !frmAVABackOrderReleaseHandling.parmApprovalSaveOpenChangesPossible()   )               // "Änderungen speichern" but nothing to save
    {
        frmAVABackOrderReleaseHandling.parmApprovalSaveOpenChanges(false);
    }

    if(     frmAVABackOrderReleaseHandling.parmReleaseFunctionsReservations()                       // "Freigabefunktionen - Reservierungen"
        ||  frmAVABackOrderReleaseHandling.parmApprovalSaveOpenChanges()        )                   // "Änderungen speichern"
    {
        if(locRemainInventQtyToReserve)  // reservable qtys found
        {
            if(!frmAVABackOrderReleaseHandling.parmReleaseFunctionReleaseMarked())                  // not "Teilfreigabe" and with this "Positionsfreigabe", "Komplettfreigabe"
            {
                locDialogButton = Box::yesNo(   "@NDX:NXAReservePositionsForThisSalesOrder",            
                                                DialogButton::Yes,
                                                "@SYS7669"
                                                );
                if (locDialogButton != DialogButton::Yes)
                {
                    frmAVABackOrderReleaseHandling.parmReleaseFunctionsReservations(false);
                }
            }
        }
        else
        {
            frmAVABackOrderReleaseHandling.parmReleaseFunctionsReservations(false);
        }
    }

    if(     frmAVABackOrderReleaseHandling.parmApprovalSaveOpenChanges()                            // "Änderungen speichern"
        &&  locReleaseFunctionReleaseMarkedSaveOpenChanges)                                         // "Änderungen speichern"
    {
        locDialogButton = Box::yesNo(   "@NDX:NXAPositionsMarkedGrantPartialRelease",
                                        DialogButton::Yes,
                                        "@NDX:NXAPartialRelease"                        
                                        );
        if (locDialogButton != DialogButton::Yes)
        {
            locReleaseFunctionReleaseMarkedSaveOpenChanges = false;
        }
    }

    // Process changes on tmpTable and InventTransferLine
    ttsbegin;
    while select forupdate AVAInventTransferLineBackOrderTmp
    {
        locInventTransferLine           = InventTransferLine::findTransIdShip(AVAInventTransferLineBackOrderTmp.InventTransId);
        frmAVABackOrderReleaseHandling.currentSetValuesTables(locInventTransferLine, AVAInventTransferLineBackOrderTmp);

        locApprovalMarkAvailableFound   = false;

        if(frmAVABackOrderReleaseHandling.parmApprovalMarkAvailable())                              // "Verfügbare markieren" - Grün markieren
        {
            if(frmAVABackOrderReleaseHandling.currentIsAvailableOrIndividual())
            {
                if(frmAVABackOrderReleaseHandling.currentReleaseIndicatorBothNo())
                {
                    locApprovalMarkAvailableFound = true;

                    if(     frmAVABackOrderReleaseHandling.parmApprovalMarkAvailablePossible()
                        &&  locInventTransferLine.AVAItemSetComponent                           )
                    {
                        locApprovalMarkAvailableFound = this.checkItemSetComponentReleasable(locInventTransferLine);
                    }

                    if(locApprovalMarkAvailableFound)
                    {
                        AVAInventTransferLineBackOrderTmp.KCS_SOCPickingReleaseIndicator    = NoYes::Yes;
                        frmAVABackOrderReleaseHandling.currentSetValuesTables(locInventTransferLine, AVAInventTransferLineBackOrderTmp);
                        tmpTableModified                                                    = true;
                    }
                }
            }
        }

        if(frmAVABackOrderReleaseHandling.parmReleaseFunctionReleaseMarked())                       // Teilfreigabe
        {
            if(frmAVABackOrderReleaseHandling.currentReleaseIndicatorNo2Yes())
            {
                if(     frmAVABackOrderReleaseHandling.parmReleasePosition()            == false    // "keine Positionsfreigabe"
                    ||  (       frmAVABackOrderReleaseHandling.parmReleasePosition()    == true     // "Positionsfreigabe"
                            &&  locSingleAVAInventTransferLineBackOrderTmpRecId
                            &&  locSingleAVAInventTransferLineBackOrderTmpRecId == AVAInventTransferLineBackOrderTmp.RecId)    )
                {
                    //processReservation();
                    locInventTransferLine.KCS_SOCPickingReleaseIndicator    = NoYes::Yes;
                    frmAVABackOrderReleaseHandling.currentSetValuesTables(locInventTransferLine, AVAInventTransferLineBackOrderTmp);
                    inventTransferLineModified                              = true;
                }
                locReleaseFunctionReleaseMarked = true;
            }
            else
            {
                locReleaseFunctionReleaseMarked = false;
            }
        }

        if(     frmAVABackOrderReleaseHandling.parmApprovalSaveOpenChanges()                        // "Änderungen speichern"
            &&  frmAVABackOrderReleaseHandling.parmApprovalSaveOpenChangesPossible()    )
        {
            if(frmAVABackOrderReleaseHandling.currentReleaseIndicatorDifferent())
            {
                locInventTransferLine.KCS_SOCPickingReleaseIndicator    = AVAInventTransferLineBackOrderTmp.KCS_SOCPickingReleaseIndicator;
                frmAVABackOrderReleaseHandling.currentSetValuesTables(locInventTransferLine, AVAInventTransferLineBackOrderTmp);
                inventTransferLineModified                              = true;

                locReleaseFunctionsShippingDateTmp  = frmAVABackOrderReleaseHandling.parmReleaseFunctionsShippingDate(); // "Freigabefunktionen - Versanddatum"
                locReleaseFunctionsReservationsTmp  = frmAVABackOrderReleaseHandling.parmReleaseFunctionsReservations(); // "Freigabefunktionen - Reservierungen"
                frmAVABackOrderReleaseHandling.parmReleaseFunctionsShippingDate(true);              // "Freigabefunktionen - Versanddatum"
                frmAVABackOrderReleaseHandling.parmReleaseFunctionsReservations(true);              // "Freigabefunktionen - Reservierungen"
            }
        }

        if(     frmAVABackOrderReleaseHandling.parmReleaseFunctionsShippingDate()                   // "Freigabefunktionen - Versanddatum"
            &&  frmAVABackOrderReleaseHandling.parmReleaseFunctionReleaseMarked()   )                        
        {
            if(     frmAVABackOrderReleaseHandling.parmReleasePosition()            == false        // "keine Positionsfreigabe"
                ||  (       frmAVABackOrderReleaseHandling.parmReleasePosition()    == true         // "Positionsfreigabe"
                        &&  locSingleAVAInventTransferLineBackOrderTmpRecId
                        &&  locSingleAVAInventTransferLineBackOrderTmpRecId == AVAInventTransferLineBackOrderTmp.RecId)    )
            {
                locShippingDate             = ReleasForShipment_ShippingDateConfirmed.dateValue();
                locShippingDateOverwrite    = ReleaseForShipment_Overwrite.checked();
                if(locShippingDate != dateNull())
                {
                    if(locShippingDate != locInventTransferLine.ShipDate && AVAInventTransferLineBackOrderTmp.KCS_SOCPickingReleaseIndicator)
                    {
                        if(locInventTransferLine.ShipDate == dateNull())
                        {
                            locInventTransferLine.ShipDate  = locShippingDate;
                            inventTransferLineModified      = true;
                        }
                        else
                        {
                            if(locShippingDateOverwrite)
                            {
                                locInventTransferLine.ShipDate  = locShippingDate;
                                inventTransferLineModified      = true;
                            }
                        }
                    }
                }
            }
        }

        if(     frmAVABackOrderReleaseHandling.parmReleaseFunctionsReservations()                   // "Freigabefunktionen - Reservierungen"
            &&  locReleaseFunctionReleaseMarked)                      
        {
            if(     frmAVABackOrderReleaseHandling.parmReleasePosition()            == false        // "keine Positionsfreigabe"
                ||  (       frmAVABackOrderReleaseHandling.parmReleasePosition()    == true         // "Positionsfreigabe"
                        &&  locSingleAVAInventTransferLineBackOrderTmpRecId
                        &&  locSingleAVAInventTransferLineBackOrderTmpRecId         == AVAInventTransferLineBackOrderTmp.RecId)    )
            {
                processReservation();

                locGetInventTransferLinesFromDB = true;
            }
        }

        if(     frmAVABackOrderReleaseHandling.parmApprovalSaveOpenChanges()                        // "Änderungen speichern"
            &&  frmAVABackOrderReleaseHandling.parmApprovalSaveOpenChangesPossible()    )
        {
            frmAVABackOrderReleaseHandling.parmReleaseFunctionsShippingDate(locReleaseFunctionsShippingDateTmp); // "Freigabefunktionen - Versanddatum"
            frmAVABackOrderReleaseHandling.parmReleaseFunctionsReservations(locReleaseFunctionsReservationsTmp); // "Freigabefunktionen - Reservierungen"

            if(     locReleaseFunctionReleaseMarkedSaveOpenChanges
                &&  AVAInventTransferLineBackOrderTmp.KCS_SOCPickingReleaseIndicator    == NoYes::Yes
                &&  locInventTransferLine.KCS_SOCPickingReleaseIndicator                != AVAInventTransferLineBackOrderTmp.KCS_SOCPickingReleaseIndicator)
            {
                processReservation();
                locInventTransferLine.KCS_SOCPickingReleaseIndicator = NoYes::Yes;
                frmAVABackOrderReleaseHandling.currentSetValuesTables(locInventTransferLine, AVAInventTransferLineBackOrderTmp);
                inventTransferLineModified                           = true;
            }
        }

        if(tmpTableModified)
        {
            AVAInventTransferLineBackOrderTmp.selectForUpdate(true);
            AVAInventTransferLineBackOrderTmp.update();
            tmpTableModified = false;
        }

        if(inventTransferLineModified)
        {
            locInventTransferLine.selectForUpdate(true);
            locInventTransferLine.update();

            locInventTransferLine.avaItemSetInventTransferLineSetKCS_SOCPickingReleaseIndicator();

            inventTransferLineModified      = false;
            locGetInventTransferLinesFromDB = true;
        }
        locInventTransferLine.avaUpdateInventTransferTableKCS_PickingReleaseIndicator();
    }
    ttscommit;

    AVAInventTransferLineBackOrderTmp_DS.refresh();
    InventTransferLine_DS.ReSearch(true);

    if(locGetInventTransferLinesFromDB == true)
    {
        element.refreshCallerForm();
    }
}

/// <summary>
///    AVA <c>processSelectedPositions</c> method.
/// </summary>
/// <returns>
///    <c>void</c> as return value
/// </returns>
private void markMissingItemSetComponents()
{
    MultiSelectionHelper    locMSHelper;
    AVAInventTransferLineBackOrderTmp   locRecordsSelected;
    AVAInventTransferLineBackOrderTmp   locAVAInventTransferLineBackOrderTmp;
    InventTransferLine      locInventTransferLine;
    InventTransferLine      locInventTransferLineSearch;

    locMSHelper             = MultiSelectionHelper::construct();

    //locMSHelper.parmDatasource(InventTransferLine_DS);
    locMSHelper.parmDatasource(AVAInventTransferLineBackOrderTmp_DS);


    //check selected positions
    locRecordsSelected = locMSHelper.getFirst();
    while (locRecordsSelected.RecId)
    {
        locInventTransferLine                   = InventTransferLine::findRecId(locRecordsSelected.InventTransferLineRefRecId);
        locAVAInventTransferLineBackOrderTmp    = locRecordsSelected;

        if(locInventTransferLine.AVAItemSetComponent)
        {
            while select locInventTransferLineSearch
            where   locInventTransferLineSearch.TransferId          == locInventTransferLine.TransferId
                &&  locInventTransferLineSearch.AVAItemSetParent    == locInventTransferLine.AVAItemSetParent
                &&  locInventTransferLineSearch.RecId               != locInventTransferLine.RecId
            {
                locAVAInventTransferLineBackOrderTmp = AVAInventTransferLineBackOrderTmp::findInventTransferLineInventTransId(locInventTransferLineSearch.InventTransId);
                if(InventTransferLine_DS.positionToRecord( locInventTransferLineSearch))
                {
                    InventTransferLine_DS.mark(true);
                }
            }
        }


        locRecordsSelected = locMSHelper.getNext();
    }
    //InventTransferLine_DS.refresh();
}

/// <summary>
///    AVA <c>markTmpTableRecord</c> method.
/// </summary>
/// <param name="_avaInventTransferLineBackOrderTmp">
///    <c>AVAInventTransferLineBackOrderTmp</c> as type
/// </param>
/// <returns>
///    <c>void</c> as return value
/// </returns>
private void markTmpTableRecord(AVAInventTransferLineBackOrderTmp _avaInventTransferLineBackOrderTmp)
{
    AVAInventTransferLineBackOrderTmp   locAVAInventTransferLineBackOrderTmp;
    InventTransferLine                  locInventTransferLine;

    locInventTransferLine = InventTransferLine::findRecId(_avaInventTransferLineBackOrderTmp.InventTransferLineRefRecId);
    if(locInventTransferLine.RecId)
    {
        if(InventTransferLine_DS.positionToRecord( locInventTransferLine))
        {
            InventTransferLine_DS.mark(true);
        }
    }
}

/// <summary>
///    AVA <c>processSelectedPositions</c> method.
/// </summary>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
private boolean processSelectedPositions()
{
    boolean                 retVal;
    boolean                 releaseCheckedWHSWork;
    boolean                 releaseCheckedReservation;
    boolean                 releaseDoPossibleRevocations;
    boolean                 releaseRevokeReservations;

    DialogButton            locDialogButton;

    int                     found;
    int                     outOf;

    //InventTransferLine                  locRecordsSelected;
    AVAInventTransferLineBackOrderTmp   locRecordsSelected;
    InventTransferLine                  locInventTransferLine;
    AVAStockAvailability                locAVAStockAvailability;
    AVAInventTransferLineBackOrderTmp   locAVAInventTransferLineBackOrderTmp;

    boolean                 locGetInventTransferLinesFromDB;

    MultiSelectionHelper    locMSHelper;

    Map                     inventTransferLineMap;
    MapEnumerator           inventTransferLineMapEnumerator;

    InventQty               locInventQtyReserved;
    InventQty               locInventQtyMarked;
    InventQty               locRemainInventQtyToReserve;

    retVal = true;

    this.markMissingItemSetComponents(); // ToDo: only for special needs

    locMSHelper             = MultiSelectionHelper::construct();
    inventTransferLineMap   = new Map(Types::Int64, Types::Record);

    //locMSHelper.parmDatasource(InventTransferLine_DS);
    locMSHelper.parmDatasource(AVAInventTransferLineBackOrderTmp_DS);

    //check selected positions
    locRecordsSelected = locMSHelper.getFirst();
    while (locRecordsSelected.RecId)
    {
        locInventTransferLine                   = InventTransferLine::findRecId(locRecordsSelected.InventTransferLineRefRecId);
        locAVAInventTransferLineBackOrderTmp    = locRecordsSelected;

        if(     frmAVABackOrderReleaseHandling.parmApprovalUnmarkUnreserveSelected() // "Aufheben"
            &&  locAVAInventTransferLineBackOrderTmp.RecId                          )
        {
            outOf++;
            if(locInventTransferLine.avaOpenWHSWorkTableExists().RecId)
            {
                found++;
                releaseCheckedWHSWork = true;
            }
            else
            {
                if (!inventTransferLineMap.exists(locInventTransferLine.RecId))
                {
                    inventTransferLineMap.insert(locInventTransferLine.RecId, locInventTransferLine);
                }
                if(!releaseCheckedReservation && locInventTransferLine.avaReservedPhysical())
                {
                    releaseCheckedReservation = true;   // reservation found in selected positions
                }
            }
        }

        if(frmAVABackOrderReleaseHandling.parmApprovalReserveSelected()) // "Reservieren"
        {
            locAVAStockAvailability = locInventTransferLine.avaGetStockAvailablity();

            if(     locAVAStockAvailability == AVAStockAvailability::Available
                ||  locAVAStockAvailability == AVAStockAvailability::PartitialAvailable )
            {
                locRemainInventQtyToReserve = locInventTransferLine.avaRemainInventQtyReservable(true);
                if(locRemainInventQtyToReserve > 0.0)
                {
                    locInventTransferLine.avaReserveInventTransferLine(locInventTransferLine, locRemainInventQtyToReserve); // reserve at least available qty
                    locGetInventTransferLinesFromDB = true;
                }
            }
        }
        locRecordsSelected = locMSHelper.getNext();
    }

    if(frmAVABackOrderReleaseHandling.parmApprovalUnmarkUnreserveSelected()) // "Aufheben"
    {
        if(releaseCheckedWHSWork)
        {
            locDialogButton = Box::okCancel(strFmt( "@NDX:NXAP1OfP2NotRevocableDoPossibleRevocation", found, outOf),
                                                    DialogButton::Cancel,
                                                    "@NDX:WIPHelp"
                                                    );
            if (locDialogButton == DialogButton::Ok)
            {
                releaseDoPossibleRevocations = true;
            }
            if(found == outOf)                      // all marked positions have WHSWork, not relevant
            {
                releaseDoPossibleRevocations = false;
            }
        }
        if(releaseCheckedReservation)
        {
            locDialogButton = Box::okCancel("@NDX:NXARevokeReservations",
                                            DialogButton::Cancel,
                                            "@NDX:NXAReservationsFound"
                                            );
            if (locDialogButton == DialogButton::Ok)
            {
                releaseRevokeReservations = true;
            }
        }
        if(frmAVABackOrderReleaseHandling.parmApprovalUnmarkUnreserveSelected())
        {
            releaseRevokeReservations = true;
        }
        // process collected positions
        ttsbegin;
        // retrieve from inventTransferLineMap
        inventTransferLineMapEnumerator = inventTransferLineMap.getEnumerator();
        while (inventTransferLineMapEnumerator.moveNext())
        {
            locInventTransferLine                   = inventTransferLineMapEnumerator.currentValue();
            locInventTransferLine                   = InventTransferLine::findRecId(locInventTransferLine.RecId, true);
            //locAVAInventTransferLineBackOrderTmp    = AVAInventTransferLineBackOrderTmp::findInventTransferLineRefRecId(locInventTransferLine.RecId, true);
            locAVAInventTransferLineBackOrderTmp    = AVAInventTransferLineBackOrderTmp;
            select firstOnly locAVAInventTransferLineBackOrderTmp
            where locAVAInventTransferLineBackOrderTmp.InventTransferLineRefRecId == locInventTransferLine.RecId;

            if(     locAVAInventTransferLineBackOrderTmp.RecId
                &&  locAVAInventTransferLineBackOrderTmp.KCS_SOCPickingReleaseIndicator == NoYes::Yes)
            {
                locAVAInventTransferLineBackOrderTmp.KCS_SOCPickingReleaseIndicator = NoYes::No;
                locAVAInventTransferLineBackOrderTmp.update();
            }
            if(     locInventTransferLine.RecId
                &&  locInventTransferLine.KCS_SOCPickingReleaseIndicator == NoYes::Yes)
            {
                locInventTransferLine.KCS_SOCPickingReleaseIndicator = NoYes::No;
                locInventTransferLine.update();

                locInventTransferLine.avaItemSetInventTransferLineSetKCS_SOCPickingReleaseIndicator();

                locInventTransferLine.avaUpdateInventTransferTableKCS_PickingReleaseIndicator();

                locGetInventTransferLinesFromDB = true;
            }

            /*******************************
            // moved to InventTransferLine.avaReservedPhysical()
            InventDim                       locInventDim;
            InventDimParm                   locInventDimParmCriteria;
            InventTransIdSumSingleStatus    locInventTransIdSumSingleStatus;

            locInventDim.clear();
            locInventDim = InventDim::findOrCreate(locInventTransferLine.inventDim());
            locInventDimParmCriteria.initFromInventDim(locInventDim);

            locInventTransIdSumSingleStatus = InventTransIdSumSingleStatus::newTransOriginIdStatus( InventTransOriginTransferShip::findInventTransOriginId( locInventTransferLine.DataAreaId,
                                                                                                                                                            locInventTransferLine.TransferId,
                                                                                                                                                            locInventTransferLine.LineNum       ),
                                                                                                    StatusReceipt::None,
                                                                                                    StatusIssue::ReservPhysical                                                                     );
            locInventTransIdSumSingleStatus.parmInventDimCriteria(locInventDim);
            locInventTransIdSumSingleStatus.parmInventDimParmCriteria(locInventDimParmCriteria);

            locInventQtyReserved = locInventTransIdSumSingleStatus.reservPhysical() * (-1);


            *******************************/

            locInventQtyReserved = locInventTransferLine.avaReservedPhysical();

            if(releaseRevokeReservations && locInventQtyReserved)
            {
                locInventQtyMarked = locInventTransferLine.qtyMarked();
                if(locInventQtyMarked <= 0)   // check marking
                {
                    locInventTransferLine.avaReserveInventTransferLine(locInventTransferLine, locInventQtyReserved, true); // unreserve qty
                    locGetInventTransferLinesFromDB = true;
                }
            }
        }
        ttscommit;
    }

    if(locGetInventTransferLinesFromDB == true)
    {
        InventTransferLine_DS.research(true);

        element.refreshCallerForm();
    }

    return retVal;
}

