/// <summary>
///    AVA <c>tmpReleaseIndicatorModified</c> method.
/// </summary>
/// <param name="_initialStatus">
///    <c>boolean</c> as type
/// </param>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean tmpReleaseIndicatorModified(boolean _initialStatus)
{
    boolean                             retVal;

    FormDataSource                      locAVAInventTransferLineBackOrderTmpDS;
    AVAInventTransferLineBackOrderTmp   locAVAInventTransferLineBackOrderTmp;
    FormDataSource                      locInventTransferLineDS;
    InventTransferLine                  locInventTransferLine;
    AVAStockAvailability                locAVAStockAvailability;
    boolean                             locInventTransferLineChanged;
    boolean                             locCheckFailed;
    boolean                             locItemSetHandling;

    Args                                dialogArgs;
    MenuFunction                        dialogMenuFunction;

    boolean                             locItemSetComponentsReleasable;
    KCS_SOCPickingReleaseIndicator      locKCS_SOCPickingReleaseIndicator;
    KCS_SOCPickingReleaseIndicator      locKCS_SOCPickingReleaseIndicatorTmp;
    AVAInventTransferLineBackOrderTmp   locAVAInventTransferLineBackOrderTmpSearch;
    InventTransferLine                  locInventTransferLineSearch;
    AVAStockAvailability                locAVAStockAvailabilitySearch;

    retVal                                  = _initialStatus;

    locAVAInventTransferLineBackOrderTmpDS  = element.AVAInventTransferLineBackOrderTmp_DS;
    locAVAInventTransferLineBackOrderTmp    = locAVAInventTransferLineBackOrderTmpDS.cursor();
    locInventTransferLineDS                 = element.InventTransferLine_DS;
    locInventTransferLine                   = locAVAInventTransferLineBackOrderTmp.inventTransferLine(); // locInventTransferLineDS.cursor();

    locAVAStockAvailability                 = locInventTransferLine.avaGetStockAvailablity();
    locItemSetHandling                      = locInventTransferLine.AVAItemSet || locInventTransferLine.AVAItemSetComponent;
    locKCS_SOCPickingReleaseIndicatorTmp    = locAVAInventTransferLineBackOrderTmp.KCS_SOCPickingReleaseIndicator;
    locKCS_SOCPickingReleaseIndicator       = locAVAInventTransferLineBackOrderTmp.KCS_SOCPickingReleaseIndicator;

    if(locAVAInventTransferLineBackOrderTmp.KCS_SOCPickingReleaseIndicator)
    {
        switch(locAVAInventTransferLineBackOrderTmp.AVAStockAvailability)
        {
            case AVAStockAvailability::Available:
                if(locItemSetHandling)
                {
                    if(locInventTransferLine.AVAItemSetComponent)
                    {
                        if(     locInventTransferLine.KCS_SOCPickingReleaseIndicator                == NoYes::No
                            &&  locAVAInventTransferLineBackOrderTmp.KCS_SOCPickingReleaseIndicator == NoYes::Yes   )
                        {
                            locItemSetComponentsReleasable = true;
                            // check availability
                            while select AVAInventTransferLineBackOrderTmp
                            {
                                locAVAInventTransferLineBackOrderTmpSearch  = AVAInventTransferLineBackOrderTmp;
                                locInventTransferLineSearch                 = locAVAInventTransferLineBackOrderTmpSearch.inventTransferLine();

                                if(     locInventTransferLineSearch.RecId
                                    &&  locInventTransferLineSearch.AVAItemSetComponent
                                    &&  locInventTransferLineSearch.AVAItemSetParent    == locInventTransferLine.AVAItemSetParent
                                    &&  locInventTransferLineSearch.InventTransId       != locInventTransferLine.InventTransId      )
                                {
                                    locAVAStockAvailabilitySearch = locInventTransferLineSearch.avaGetStockAvailablity();

                                    if(locAVAStockAvailabilitySearch != AVAStockAvailability::Available)
                                    {
                                        locItemSetComponentsReleasable = false;
                                    }
                                }
                            }
                        }
                    }
                }
                /*
                else
                {
                    locAVAInventTransferLineBackOrderTmp.KCS_SOCPickingReleaseIndicator = NoYes::Yes;
                }
                */
                break;

            case AVAStockAvailability::PartitialAvailable:
                dialogArgs          = new Args();
                dialogArgs.record(locAVAInventTransferLineBackOrderTmp);
                dialogArgs.caller(element);
                dialogMenuFunction  = new MenuFunction(menuItemDisplayStr(AVASalesLineBackOrderReservation), MenuItemType::Display);
                //dialogMenuFunction.run(dialogArgs); //ToDo: Replacment for AVASalesLineBackOrderReservation needed
                locInventTransferLineChanged = true;
                break;

            case AVAStockAvailability::NotAvailable:
                locCheckFailed      = checkFailed("@NDX:NXAReleaseForShipmentNotPossibleNoStock");
                ttsBegin;
                locAVAInventTransferLineBackOrderTmp.selectForUpdate(true);
                locAVAInventTransferLineBackOrderTmp.KCS_SOCPickingReleaseIndicator = NoYes::No;
                locAVAInventTransferLineBackOrderTmp.update();
                ttsCommit;
                break;

            case AVAStockAvailability::IndividualRequired:
            case AVAStockAvailability::Unknown:
                ttsBegin;
                locAVAInventTransferLineBackOrderTmp.selectForUpdate(true);
                locAVAInventTransferLineBackOrderTmp.KCS_SOCPickingReleaseIndicator = NoYes::No;
                locAVAInventTransferLineBackOrderTmp.update();
                ttsCommit;
                break;
        }

    }
    else
    {
        switch(locAVAInventTransferLineBackOrderTmp.AVAStockAvailability)
        {
            case AVAStockAvailability::PartitialAvailable:
                ttsBegin;
                locAVAInventTransferLineBackOrderTmp.selectForUpdate(true);
                locAVAInventTransferLineBackOrderTmp.InventTransferQtyPossible      = 0;
                locAVAInventTransferLineBackOrderTmp.InventTransferQtyEffective     = 0;
                locAVAInventTransferLineBackOrderTmp.KCS_SOCPickingReleaseIndicator = NoYes::No;
                locAVAInventTransferLineBackOrderTmp.update();
                ttsCommit;
                break;
        }
    }

    if(locInventTransferLine.AVAItemSetComponent)
    {
        if(     (locItemSetComponentsReleasable         == true && locKCS_SOCPickingReleaseIndicatorTmp == NoYes::Yes)      // from No to Yes
            ||  locKCS_SOCPickingReleaseIndicatorTmp    == NoYes::No                                                        // deactivation always possible
            ||  locKCS_SOCPickingReleaseIndicatorTmp    == locKCS_SOCPickingReleaseIndicator                            )   // back to original always possible
        {
            ttsbegin;
            while select forupdate AVAInventTransferLineBackOrderTmp
            {
                locAVAInventTransferLineBackOrderTmpSearch  = AVAInventTransferLineBackOrderTmp;
                locInventTransferLineSearch                 = locAVAInventTransferLineBackOrderTmpSearch.inventTransferLine();

                if(     locInventTransferLineSearch.RecId
                    &&  locInventTransferLineSearch.AVAItemSetComponent
                    &&  locInventTransferLineSearch.AVAItemSetParent == locInventTransferLine.AVAItemSetParent  )
                {
                    AVAInventTransferLineBackOrderTmp.KCS_SOCPickingReleaseIndicator = locKCS_SOCPickingReleaseIndicatorTmp;
                    AVAInventTransferLineBackOrderTmp.update();
                }
            }
            ttscommit;
            //AVAInventTransferLineBackOrderTmp_DS.refresh();
            InventTransferLine_DS.ReSearch(true);
        }
    }

    if(locInventTransferLineChanged)
    {
        locInventTransferLineDS.reread();
        locInventTransferLineDS.refresh();
    }
    locAVAInventTransferLineBackOrderTmpDS.refresh();

    return retVal;
}

/// <summary>
///    AVA <c>checkItemSetRelease</c> method.
/// </summary>
/// <param name="_InventTransferLine">
///    <c>InventTransferLine</c> as type
/// </param>
/// <param name="_singleAVAInventTransferLineBackOrderTmp">
///    <c>AVAInventTransferLineBackOrderTmp</c> as type
/// </param>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
private boolean checkItemSetComponentReleasable(InventTransferLine                   _InventTransferLine,
                                                AVAInventTransferLineBackOrderTmp    _singleAVAInventTransferLineBackOrderTmp = null)
{
    boolean                             retVal;

    FormDatasource                      locInventTransferLineDS;
    InventTransferLine                  locInventTransferLine;
    AVAStockAvailability                locAVAStockAvailability;

    locAVAStockAvailability = AVAStockAvailability::Available;

    if(_InventTransferLine.AVAItemSetComponent)
    {
        locInventTransferLineDS = element.InventTransferLine_DS;
        locInventTransferLine   = InventTransferLine_DS.getFirst() as InventTransferLine;
        while(locInventTransferLine)
        {
            if(     (       locAVAStockAvailability         == AVAStockAvailability::Available 
                        ||  locAVAStockAvailability         == AVAStockAvailability::IndividualRequired )
                &&  locInventTransferLine.AVAItemSetComponent
                &&  locInventTransferLine.AVAItemSetParent  == _InventTransferLine.AVAItemSetParent
                &&  locInventTransferLine.RecId             != _InventTransferLine.RecId            )
            {
                locAVAStockAvailability = locInventTransferLine.avaGetStockAvailablity();
            }
            locInventTransferLine = InventTransferLine_DS.getNext() as InventTransferLine;
        }

        if(     locAVAStockAvailability == AVAStockAvailability::Available
            ||  locAVAStockAvailability == AVAStockAvailability::IndividualRequired )
        {
            retVal = true;
        }
    }
    return retVal;
}

/// <summary>
///    AVA <c>getIventTransferLineMap</c> method.
/// </summary>
/// <returns>
///    <c>Map</c> as return value
/// </returns>
public Map getIventTransferLineMap()
{
    Map                                 locMapInventTransferLine;
    MultiSelectionHelper                locMSHelper;
    AVAInventTransferLineBackOrderTmp   locRecordsSelected;
    InventTransferLine                  locInventTransferLine;
    AVAInventTransferLineBackOrderTmp   locAVAInventTransferLineBackOrderTmp;


    locMapInventTransferLine    = new Map(Types::Int64, Types::Record);

    locMSHelper                 = MultiSelectionHelper::construct();
    locMSHelper.parmDatasource(AVAInventTransferLineBackOrderTmp_DS);

    //check selected positions
    locRecordsSelected = locMSHelper.getFirst();
    while (locRecordsSelected.RecId)
    {
        locInventTransferLine                   = InventTransferLine::findRecId(locRecordsSelected.InventTransferLineRefRecId);
        locAVAInventTransferLineBackOrderTmp    = locRecordsSelected;

        if (!locMapInventTransferLine.exists(locInventTransferLine.RecId))
        {
            locMapInventTransferLine.insert(locInventTransferLine.RecId, locInventTransferLine);
        }
        locRecordsSelected = locMSHelper.getNext();
    }

    return locMapInventTransferLine;
}

