/// <summary>
///    AVA <c>displayOption</c> method.
/// </summary>
/// <param name="_record">
///    <c>Common</c> as type
/// </param>
/// <param name="_options">
///    <c>FormRowDisplayOption</c> as type
/// </param>
public void displayOption(Common _record, FormRowDisplayOption _options)
{
    InventTransferLine  locInventTransferLine;

    int                 locItemSetColor;
    int                 locItemSetColorExpanded;
    int                 locItemSetColorComponent;

    super(_record, _options);

    locInventTransferLine           = _record;

    if(element.frmAVAItemSetParameters.RecId)
    {
        locItemSetColor             = element.frmAVAItemSetParameters.ItemSetBGColor;
        locItemSetColorExpanded     = element.frmAVAItemSetParameters.ItemSetBGColorExpanded;
        locItemSetColorComponent    = element.frmAVAItemSetParameters.ItemSetBGColorComponent;
    }
    else
    {
        locItemSetColor             = 16744576; // FF8080 or 255,128,128 or WinAPI::RGB2int(255, 128, 128)    // light red
        locItemSetColorExpanded     = 65505;    // 00FFE1 or 0,255,255  or WinAPI::RGB2int(0, 255, 255)       // turquoise
        locItemSetColorComponent    = 8454118;  // 80FFE6 or 128,255,255  or WinAPI::RGB2int(128, 255, 255)   // light turquoise
    }

    if(     locInventTransferLine.AVAItemSetExpanded
    &&  locItemSetColorExpanded                 )
    {
        _options.backColor(locItemSetColorExpanded);
    }
    else if(    locInventTransferLine.AVAItemSet
        &&  locItemSetColor                 )
    {
        _options.backColor(locItemSetColor);
    }
    else if(    locInventTransferLine.AVAItemSetParent
        &&  locItemSetColorComponent            )
    {
        _options.backColor(locItemSetColorComponent);
    }
    /*
    else
    {
    _options.clearBackColor();
    }
    */
}

